/* global __CONFIG__ */
/* eslint-disable @typescript-eslint/no-require-imports */
import cf from 'cloudfront';

// cognito-at-edge for CloudFront Functions (cloudfront-js-2.0, viewer request).
// Generated by cloudfront-functions/build.js; __CONFIG__ is replaced with the settings.
//   valid token cookie        -> forward, no network call
//   expired token + refresh   -> one cf.fetch POST /oauth2/token (refresh_token), set cookies, 302
//   callback ?code=&state=    -> one cf.fetch POST /oauth2/token (authorization_code + PKCE), set cookies, 302
//   logout path               -> one cf.fetch POST /oauth2/revoke, clear cookies, 302
//   anything else             -> 302 to the hosted UI, state + PKCE verifier in a cookie
// Cognito unreachable -> 503 on the paths that need it (fail closed).
// Public keys come from KeyValueStore, key 'jwk.<kid>', value { "n": ..., "e": ... }.

const C = __CONFIG__;
const ISSUER =
	'https://cognito-idp.' + C.region + '.amazonaws.com/' + C.userPoolId;
const BASE = 'CognitoIdentityServiceProvider.' + C.userPoolAppId;
const STATE_COOKIE = BASE + '.state';
const EXPIRED = 'Thu, 01 Jan 1970 00:00:00 GMT';
const NO_CACHE = 'no-cache, no-store, max-age=0, must-revalidate';

function b64url(bytes) {
	return Buffer.from(bytes).toString('base64url');
}

function json(part) {
	return JSON.parse(Buffer.from(part, 'base64url').toString());
}

// { header, payload, parts } or null. No signature check.
function decode(token) {
	const parts = String(token).split('.');
	if (parts.length !== 3) return null;
	try {
		return { header: json(parts[0]), payload: json(parts[1]), parts: parts };
	} catch (_e) {
		return null;
	}
}

// Every claim except exp. The token cookie names the token type the site checks.
function claimsOk(p, use) {
	const audience = use === 'access' ? p.client_id : p.aud;
	return (
		p.iss === ISSUER && p.token_use === use && audience === C.userPoolAppId
	);
}

// RS256 signature with the key KVS holds for the token's kid. WebCrypto only after any
// network call: the runtime forbids a call once a non-deterministic crypto operation ran.
async function signatureOk(d) {
	if (d.header.alg !== 'RS256' || !d.header.kid) return false;
	let jwk;
	try {
		const value = await cf.kvs().get('jwk.' + d.header.kid);
		jwk = JSON.parse(value);
	} catch (_e) {
		return false;
	}
	const subtle = require('webcrypto').subtle;
	const alg = { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' };
	const key = await subtle.importKey(
		'jwk',
		{ kty: 'RSA', n: jwk.n, e: jwk.e, alg: 'RS256', ext: true },
		alg,
		false,
		['verify'],
	);
	const signature = Buffer.from(d.parts[2], 'base64url');
	const data = Buffer.from(d.parts[0] + '.' + d.parts[1]);
	return subtle.verify(alg, key, signature, data);
}

async function verify(token, use, now) {
	const d = decode(token);
	if (!d || !claimsOk(d.payload, use) || !(d.payload.exp > now)) return null;
	const ok = await signatureOk(d);
	return ok ? d.payload : null;
}

// The token cookies of the last signed-in user (the names Lambda@Edge cognito-at-edge writes).
function readTokens(cookies) {
	let user = cookies[BASE + '.LastAuthUser']
		? cookies[BASE + '.LastAuthUser'].value
		: '';
	if (!user) {
		for (const name in cookies) {
			const m =
				name.indexOf(BASE + '.') === 0 &&
				/^(.+)\.(idToken|accessToken|refreshToken)$/.exec(
					name.slice(BASE.length + 1),
				);
			if (m) user = m[1];
		}
	}
	const get = (kind) =>
		(cookies[BASE + '.' + user + '.' + kind] || {}).value || '';
	return {
		user: user,
		token: get(C.tokenUse === 'access' ? 'accessToken' : 'idToken'),
		refresh: get('refreshToken'),
	};
}

function attributes(expires, httpOnly) {
	let a = 'Secure; Path=' + C.cookiePath + '; Expires=' + expires;
	if (C.cookieDomain) a += '; Domain=' + C.cookieDomain;
	if (httpOnly) a += '; HttpOnly';
	if (C.sameSite) a += '; SameSite=' + C.sameSite;
	return a;
}

function redirect(location, cookies) {
	return {
		statusCode: 302,
		statusDescription: 'Found',
		headers: {
			location: { value: location },
			'cache-control': { value: NO_CACHE },
		},
		cookies: cookies || {},
	};
}

function page(status, code, detail) {
	const headers = {
		'content-type': { value: 'application/json' },
		'cache-control': { value: NO_CACHE },
	};
	if (detail)
		headers['x-cognito-at-edge-error'] = {
			value: String(detail).slice(0, 200),
		};
	return {
		statusCode: status,
		statusDescription: code,
		headers: headers,
		body: JSON.stringify({ error: code }),
	};
}

function queryString(q) {
	const out = [];
	for (const name in q) {
		const v = q[name];
		const values = v.multiValue ? v.multiValue : [v];
		for (let i = 0; i < values.length; i++)
			out.push(name + (values[i].value === '' ? '' : '=' + values[i].value));
	}
	return out.join('&');
}

function form(fields) {
	const out = [];
	for (const name in fields)
		out.push(name + '=' + encodeURIComponent(fields[name]));
	return out.join('&');
}

function redirectUri(host) {
	return 'https://' + host + C.parseAuthPath;
}

// No valid session: 302 to the hosted UI. state and the PKCE verifier are random, so this
// path never makes a network call afterwards.
function login(request, host, extraCookies) {
	const wc = require('webcrypto');
	const state = b64url(wc.getRandomValues(new Uint8Array(16)));
	const verifier = b64url(wc.getRandomValues(new Uint8Array(32)));
	const challenge = require('crypto')
		.createHash('sha256')
		.update(verifier)
		.digest('base64url');
	const qs = queryString(request.querystring);
	const back = request.uri + (qs ? '?' + qs : '');
	const cookies = extraCookies || {};
	cookies[STATE_COOKIE] = {
		value: state + '.' + verifier + '.' + b64url(back),
		attributes:
			'Secure; HttpOnly; Path=' + C.cookiePath + '; Max-Age=600; SameSite=Lax',
	};
	const location =
		'https://' +
		C.userPoolDomain +
		'/oauth2/authorize?' +
		form({
			response_type: 'code',
			client_id: C.userPoolAppId,
			redirect_uri: redirectUri(host),
			state: state,
			code_challenge: challenge,
			code_challenge_method: 'S256',
		});
	return redirect(location, cookies);
}

// The one network call. Resolves to { ok, status, body } or throws (TypeError, TimeoutError, InternalError).
async function cognito(path, fields) {
	const res = await cf.fetch(path, {
		originId: C.cognitoOriginId,
		method: 'POST',
		headers: { 'content-type': 'application/x-www-form-urlencoded' },
		body: form(fields),
		includeBody: true,
	});
	const text = await res.text();
	let body = {};
	try {
		body = JSON.parse(text);
	} catch (_e) {
		body = {};
	}
	return { ok: res.ok, status: res.status, body: body };
}

// Verify the tokens Cognito just issued, set the cookies, 302 back to the page.
async function signedIn(tokens, back, now, refreshToken) {
	const use = C.tokenUse === 'access' ? 'access' : 'id';
	const payload = await verify(
		use === 'access' ? tokens.access_token : tokens.id_token,
		use,
		now,
	);
	if (!payload)
		return page(
			502,
			'token_verification_failed',
			'is jwk.<kid> in the KeyValueStore?',
		);
	const user =
		use === 'access' ? payload.username : payload['cognito:username'];
	const prefix = BASE + '.' + user + '.';
	const exp = new Date(
		(now + C.cookieExpirationDays * 86400) * 1000,
	).toUTCString();
	const a = attributes(exp, C.httpOnly);
	const cookies = {};
	cookies[prefix + 'idToken'] = { value: tokens.id_token, attributes: a };
	cookies[prefix + 'accessToken'] = {
		value: tokens.access_token,
		attributes: a,
	};
	if (refreshToken)
		cookies[prefix + 'refreshToken'] = { value: refreshToken, attributes: a };
	cookies[prefix + 'tokenScopesString'] = {
		value: 'phone email profile openid aws.cognito.signin.user.admin',
		attributes: a,
	};
	cookies[BASE + '.LastAuthUser'] = { value: user, attributes: a };
	cookies[STATE_COOKIE] = { value: '', attributes: attributes(EXPIRED, true) };
	return redirect(back, cookies);
}

// Only same-site paths: never an open redirect.
function safePath(path) {
	return path.charAt(0) === '/' &&
		path.charAt(1) !== '/' &&
		path.charAt(1) !== '\\'
		? path
		: '/';
}

async function callback(request, host, cookies, now) {
	const q = request.querystring;
	const code = q.code ? q.code.value : '';
	const saved = cookies[STATE_COOKIE]
		? cookies[STATE_COOKIE].value.split('.')
		: [];
	if (!code) return page(400, 'missing_code', q.error ? q.error.value : '');
	if (saved.length !== 3 || !q.state || q.state.value !== saved[0])
		return page(400, 'invalid_state');
	let res;
	try {
		res = await cognito('/oauth2/token', {
			grant_type: 'authorization_code',
			client_id: C.userPoolAppId,
			code: code,
			redirect_uri: redirectUri(host),
			code_verifier: saved[1],
		});
	} catch (error) {
		return page(503, 'auth_unavailable', error.name + ': ' + error.message);
	}
	if (!res.ok)
		return page(
			400,
			'token_exchange_failed',
			res.status + ' ' + (res.body.error || ''),
		);
	let back = '/';
	try {
		back = safePath(Buffer.from(saved[2], 'base64url').toString());
	} catch (_e) {
		back = '/';
	}
	return signedIn(
		res.body,
		'https://' + host + back,
		now,
		res.body.refresh_token,
	);
}

function clearAll(cookies) {
	const out = {};
	for (const name in cookies) {
		if (name.indexOf(BASE + '.') === 0)
			out[name] = { value: '', attributes: attributes(EXPIRED, C.httpOnly) };
	}
	return out;
}

async function logout(host, cookies, tokens) {
	if (tokens.refresh) {
		try {
			await cognito('/oauth2/revoke', {
				token: tokens.refresh,
				client_id: C.userPoolAppId,
			});
		} catch (_e) {
			// Cookies are cleared anyway, as Lambda@Edge cognito-at-edge does.
		}
	}
	let location =
		C.logoutRedirectUri.charAt(0) === '/'
			? 'https://' + host + C.logoutRedirectUri
			: C.logoutRedirectUri;
	if (C.cognitoLogout) {
		location =
			'https://' +
			C.userPoolDomain +
			'/logout?' +
			form({ client_id: C.userPoolAppId, logout_uri: location });
	}
	return redirect(location, clearAll(cookies));
}

async function refresh(request, host, cookies, tokens, now) {
	let res;
	try {
		res = await cognito('/oauth2/token', {
			grant_type: 'refresh_token',
			client_id: C.userPoolAppId,
			refresh_token: tokens.refresh,
		});
	} catch (error) {
		return page(503, 'auth_unavailable', error.name + ': ' + error.message);
	}
	// A refresh token Cognito rejects (expired, revoked): start over at the hosted UI.
	if (!res.ok) return login(request, host, clearAll(cookies));
	const qs = queryString(request.querystring);
	return signedIn(
		res.body,
		'https://' + host + request.uri + (qs ? '?' + qs : ''),
		now,
		'',
	);
}

// Called by CloudFront.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
async function handler(event) {
	const request = event.request;
	const host = request.headers.host.value;
	const cookies = request.cookies || {};
	const now = Math.floor(Date.now() / 1000);

	if (request.uri === C.parseAuthPath)
		return callback(request, host, cookies, now);
	const tokens = readTokens(cookies);
	if (C.logoutPath && request.uri === C.logoutPath)
		return logout(host, cookies, tokens);

	const d = tokens.token ? decode(tokens.token) : null;
	const claims = d && claimsOk(d.payload, C.tokenUse);
	if (claims && d.payload.exp > now) {
		const ok = await signatureOk(d);
		return ok ? request : login(request, host);
	}
	// Expired (or no token cookie) with a refresh token: one call, decided before any WebCrypto.
	if (tokens.refresh && (!tokens.token || claims))
		return refresh(request, host, cookies, tokens, now);
	return login(request, host);
}
